package tw.com.tft.documentscanner;import android.app.*;import android.content.*;import android.content.res.ColorStateList;import android.net.*;import android.os.*;import android.widget.*;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.AppCompatActivity;import androidx.core.content.FileProvider;import com.google.android.material.button.*;import com.google.mlkit.vision.documentscanner.*;import java.io.*;import java.util.*;import tw.com.tft.documentscanner.session.ScanSessionStore;import tw.com.tft.documentscanner.util.UiUtils;public class MainActivity extends AppCompatActivity{private ScanSessionStore store;private File cam;private MaterialButton ai,gallery,camera;private final ActivityResultLauncher<String> gl=registerForActivityResult(new ActivityResultContracts.GetMultipleContents(),this::picked);private final ActivityResultLauncher<Uri> cl=registerForActivityResult(new ActivityResultContracts.TakePicture(),ok->{if(ok&&cam!=null&&cam.length()>0){store.startNew(this,"CAMERA");store.addLocalFile(this,cam,"CAMERA");open();}else if(cam!=null)cam.delete();});private final ActivityResultLauncher<IntentSenderRequest> ml=registerForActivityResult(new ActivityResultContracts.StartIntentSenderForResult(),r->{if(r.getResultCode()!=Activity.RESULT_OK)return;try{GmsDocumentScanningResult s=GmsDocumentScanningResult.fromActivityResultIntent(r.getData());if(s==null||s.getPages()==null||s.getPages().isEmpty())return;store.startNew(this,"AI");int n=0;for(GmsDocumentScanningResult.Page p:s.getPages()){if(n++>=10)break;store.importUri(this,p.getImageUri(),"AI");}open();}catch(Exception e){launchCamera();}});protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);UiUtils.applyInsets(this,findViewById(R.id.rootMain),true);store=ScanSessionStore.get(this);ai=findViewById(R.id.btnAiScan);gallery=findViewById(R.id.btnGallery);camera=findViewById(R.id.btnCamera);ai.setOnClickListener(v->launchAi());gallery.setOnClickListener(v->gl.launch("image/*"));camera.setOnClickListener(v->launchCamera());themes();}private void picked(List<Uri>u){if(u==null||u.isEmpty())return;store.startNew(this,"GALLERY");try{for(int i=0;i<Math.min(10,u.size());i++)store.importUri(this,u.get(i),"GALLERY");if(u.size()>10)Toast.makeText(this,"單次最多 10 張，已取前 10 張。",Toast.LENGTH_LONG).show();open();}catch(Exception e){Toast.makeText(this,"讀取失敗",Toast.LENGTH_LONG).show();}}private void launchAi(){GmsDocumentScannerOptions o=new GmsDocumentScannerOptions.Builder().setGalleryImportAllowed(true).setPageLimit(10).setResultFormats(GmsDocumentScannerOptions.RESULT_FORMAT_JPEG).setScannerMode(GmsDocumentScannerOptions.SCANNER_MODE_FULL).build();GmsDocumentScanner s=GmsDocumentScanning.getClient(o);s.getStartScanIntent(this).addOnSuccessListener(x->ml.launch(new IntentSenderRequest.Builder(x).build())).addOnFailureListener(e->{Toast.makeText(this,"AI 掃描不可用，改用本機拍照。",Toast.LENGTH_LONG).show();launchCamera();});}private void launchCamera(){try{File d=new File(getCacheDir(),"scan_originals");d.mkdirs();cam=new File(d,"camera_"+System.currentTimeMillis()+".jpg");cl.launch(FileProvider.getUriForFile(this,getPackageName()+".files",cam));}catch(Exception e){Toast.makeText(this,"相機無法啟動",Toast.LENGTH_LONG).show();}}private void open(){store.session().currentIndex=0;store.persist(this);startActivity(new Intent(this,CropActivity.class));}private void themes(){MaterialButtonToggleGroup g=findViewById(R.id.themeGroup);String s=getSharedPreferences("ui",MODE_PRIVATE).getString("accent","blue");int id="mint".equals(s)?R.id.themeMint:"orange".equals(s)?R.id.themeOrange:"black".equals(s)?R.id.themeBlack:R.id.themeBlue;g.check(id);accent(s);g.addOnButtonCheckedListener((x,i,c)->{if(!c)return;String n=i==R.id.themeMint?"mint":i==R.id.themeOrange?"orange":i==R.id.themeBlack?"black":"blue";getSharedPreferences("ui",MODE_PRIVATE).edit().putString("accent",n).apply();accent(n);});}private void accent(String s){int c=UiUtils.parseAccent(s);ai.setBackgroundTintList(ColorStateList.valueOf(c));gallery.setStrokeColor(ColorStateList.valueOf(c));camera.setStrokeColor(ColorStateList.valueOf(c));}}